window.ScripturaLexicons.DGP.entriesHtml += "<article id=\"entry-dgp-40801\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τροχός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1343 na letra τ · nº geral 40801</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 roda; roda de carro 2 roda de oleiro 3 roda de suplício 4 aro; arco; anel 5 espiral de serpente 6 disco (de atletismo) 7 disco solar 8 torta redonda 9 engenho de assédio 10 área circular de terra, de mar. 〈τρέχω〉</p></section></article>\n<article id=\"entry-dgp-40802\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τρύβλιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1344 na letra τ · nº geral 40802</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">prato.</p></section></article>\n<article id=\"entry-dgp-40803\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τρυγάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1345 na letra τ · nº geral 40803</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ἐτρύγων, fut. τρυγήσω, aor. ἐτρύγησα; pas. perf. part. τετρυγημένος) 1 recolher; colher 2 ceifar; segar 3 colher a uva; vindimar. 〈τρύγη〉</p></section></article>\n<article id=\"entry-dgp-40804\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τρύγησις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1346 na letra τ · nº geral 40804</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 colheita 2 colheita da uva; vindima. 〈τρυγάω〉</p></section></article>\n<article id=\"entry-dgp-40805\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τρύγητος, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 1347 na letra τ · nº geral 40805</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e τριγητός, οῦ (ὁ) 1 colheita 2 colheita da uva; vindima 3 época da colheita. 〈τρυγάω〉</p></section></article>\n<article id=\"entry-dgp-40806\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τρυγηφάγος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1348 na letra τ · nº geral 40806</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que devora as colheitas. 〈τρύγη, φαγεῖν〉</p></section></article>\n<article id=\"entry-dgp-40807\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τρυγίας, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1349 na letra τ · nº geral 40807</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">vinho com sedimentos. 〈τρύξ〉</p></section></article>\n<article id=\"entry-dgp-40808\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τρύγοιπος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1350 na letra τ · nº geral 40808</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">filtro para o vinho. 〈τρύξ, ἴπος〉</p></section></article>\n<article id=\"entry-dgp-40809\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τρυγός</h1><div class=\"entry-meta\"><span>DGP · ordem 1351 na letra τ · nº geral 40809</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. de τρύξ.</p></section></article>\n<article id=\"entry-dgp-40810\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τρυγῴεν</h1><div class=\"entry-meta\"><span>DGP · ordem 1352 na letra τ · nº geral 40810</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3a pl. pres. opt. ép., τρυγόωσιν 3a pl. pres. ind. ép., de τρυγάω.</p></section></article>\n<article id=\"entry-dgp-40811\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τρυγώδης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 1353 na letra τ · nº geral 40811</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 semelhante a borra ♦ τὸ τρυγῶδες 2 borra do vinho. 〈τρύξ, -ωδης〉</p></section></article>\n<article id=\"entry-dgp-40812\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τρυγῳδός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1354 na letra τ · nº geral 40812</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cantor de comédias ou poeta cômico. 〈τρύξ, ᾠδή〉</p></section></article>\n<article id=\"entry-dgp-40813\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τρυγών, όνος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1355 na letra τ · nº geral 40813</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 rola, pássaro 2 espécie de arraia 3 espécie de quadrúpede ovíparo.</p></section></article>\n<article id=\"entry-dgp-40814\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τρύζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1356 na letra τ · nº geral 40814</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. ἔτρυξα) 1 gorjear; arrulhar 2 balbuciar 3 murmurar 4 resmungar.</p></section></article>\n<article id=\"entry-dgp-40815\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τρυηλίς, ίδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1357 na letra τ · nº geral 40815</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">colher; pá.</p></section></article>\n<article id=\"entry-dgp-40816\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τρυμαλιά, ᾶς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1358 na letra τ · nº geral 40816</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">buraco; orifício (da agulha).〈τρύω〉</p></section></article>\n<article id=\"entry-dgp-40817\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τρύξ, τρυγός (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1359 na letra τ · nº geral 40817</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 vinho novo, não fermentado; vinho doce 2 Medic. vinho de bagaço de uva; vinhete 3 borra de vinho ou de óleo 4 Medic. sedimento (de sangue) 5 escória (de metal) 6 resíduo de voz, ref. ao eco 7 com., resíduo velho (pessoa).</p></section></article>\n<article id=\"entry-dgp-40818\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τρύπανον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1360 na letra τ · nº geral 40818</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 trado; verruma 2 Medic. trépano 3 artefato para fazer fogo. 〈τρυπάω〉</p></section></article>\n<article id=\"entry-dgp-40819\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τρυπάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1361 na letra τ · nº geral 40819</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">perfurar; furar; transpassar, ac.</p></section></article>\n<article id=\"entry-dgp-40820\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τρύπημα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1362 na letra τ · nº geral 40820</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 buraco 2 furo. 〈τρυπάω〉</p></section></article>\n<article id=\"entry-dgp-40821\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τρυσάνωρ, ορος</h1><div class=\"entry-meta\"><span>DGP · ordem 1363 na letra τ · nº geral 40821</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) desgastante; penoso; doloroso. 〈τρύω, ἀνήρ〉</p></section></article>\n<article id=\"entry-dgp-40822\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τρυτάνη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1364 na letra τ · nº geral 40822</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">balança.</p></section></article>\n<article id=\"entry-dgp-40823\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Τρύφαινα, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1365 na letra τ · nº geral 40823</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Trifena, n. de m.</p></section></article>\n<article id=\"entry-dgp-40824\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τρυφάλεια, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1366 na letra τ · nº geral 40824</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 elmo 2 elmo com um furo para fixar o penacho. 〈τρύω, φάλος〉</p></section></article>\n<article id=\"entry-dgp-40825\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τρυφάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1367 na letra τ · nº geral 40825</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ser delicado, efeminado, voluptuoso; viver na indolência; part. τρυφῶν mole, efeminado, voluptuoso, τὸ τρυφῶν ar. indolência 2 viver desregradamente, licenciosamente 3 dar-se ares; ser arrogante, presunçoso. 〈τρυφή〉</p></section></article>\n<article id=\"entry-dgp-40826\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τρυφερός, ά, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1368 na letra τ · nº geral 40826</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 delicado; macio 2 meigo; terno (pessoa) 3 efeminado; lascivo ♦ τὸ τρυφερόν 4 moleza; frouxidão: τρυφερὸς ἀνέχεσθαι παρρησίας plut. muito fraco para aguentar a franqueza ♦ τρυφερόν adv. 5 frouxamente; fracamente.</p></section></article>\n<article id=\"entry-dgp-40827\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τρυφή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1369 na letra τ · nº geral 40827</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 suavidade; delicadeza 2 indolência; vida indolente e sensual.</p></section></article>\n<article id=\"entry-dgp-40828\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τρύφημα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1370 na letra τ · nº geral 40828</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 objeto de prazer, de satisfação 2 espécie de adorno feminino. 〈τρυφάω〉</p></section></article>\n<article id=\"entry-dgp-40829\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Τρυφῶσα, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1371 na letra τ · nº geral 40829</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. Trifosa, n. de m.</p></section></article>\n<article id=\"entry-dgp-40830\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τρῦχος, εος-ους (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1372 na letra τ · nº geral 40830</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 andrajo; trapo; farrapo 2 pl. roupa rasgada; roupa de luto. 〈τρύχω〉</p></section></article>\n<article id=\"entry-dgp-40831\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τρυχόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1373 na letra τ · nº geral 40831</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. ἐτρύχωσα, pas. perf. part. τετρυγημένος) = τρύχω.</p></section></article>\n<article id=\"entry-dgp-40832\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τρύχω</h1><div class=\"entry-meta\"><span>DGP · ordem 1374 na letra τ · nº geral 40832</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. τρύξω, aor. e perf. desus.) 1 gastar; consumir; esgotar; arruinar: τ. οἶκον hom. arruinar uma casa, τρ. ἑαυτόν hom. consumir-se (de tristeza) ♦ pas. 2 ser consumido; consumir-se (de fome, de sede), dat. 3 consumir-se de desejo por alguém, gen.</p></section></article>\n<article id=\"entry-dgp-40833\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τρύω</h1><div class=\"entry-meta\"><span>DGP · ordem 1375 na letra τ · nº geral 40833</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. τρύσω, aor. e perf. desus.; pas. só perf. τέτρυμαι) 1 consumir; esgotar; exaurir ♦ pas. 2 ser consumido; ser esgotado: τ. ταλαιπωρίῃσι her. ser consumido pelos sofrimentos, τετρῦσθαι ἐς τὸ ἔσχατον κακοῦ her. ser reduzido à extrema penúria.</p></section></article>\n<article id=\"entry-dgp-40834\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Τρωαί, ῶν (αἱ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1376 na letra τ · nº geral 40834</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">troianas.</p></section></article>\n<article id=\"entry-dgp-40835\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Τρῳάς, άδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1377 na letra τ · nº geral 40835</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Τρωϊάς.</p></section></article>\n<article id=\"entry-dgp-40836\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τρωγάλιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1378 na letra τ · nº geral 40836</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 guloseimas de sobremesa; sobremesa 2 frutas secas (nozes, amêndoas etc.). 〈τρώγω〉</p></section></article>\n<article id=\"entry-dgp-40837\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Τρώγιλος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1379 na letra τ · nº geral 40837</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Trogilo, porto.</p></section></article>\n<article id=\"entry-dgp-40838\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τρώγλη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1380 na letra τ · nº geral 40838</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">buraco feito por um animal roedor. 〈τρώγω〉</p></section></article>\n<article id=\"entry-dgp-40839\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τρωγλοδύτης, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 1381 na letra τ · nº geral 40839</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) 1 que mora em buracos ♦ ὁ τρωγλοδύτης 2 carricinha, pássaro ♦ οἱ Τρωγλοδύται 3 trogloditas, povo etíope que vivia em cavernas. 〈τρώγλη, δύνω〉</p></section></article>\n<article id=\"entry-dgp-40840\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τρωγλοδυτικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1382 na letra τ · nº geral 40840</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de ou para habitantes de buracos 2 de ou relativo ao povo troglodita. 〈τρωγλοδύτης〉</p></section></article>\n<article id=\"entry-dgp-40841\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τρώγω</h1><div class=\"entry-meta\"><span>DGP · ordem 1383 na letra τ · nº geral 40841</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. τρώξομαι, aor.1 ἔτρωξα, aor.2 ἔτραγον; perf. pas. τέτρωγμαι) 1 (animal) comer; roer (ervas, folhas); pastar 2 (pessoa) comer alimentos crus 3 trincar (nozes e amêndoas) 4 comer.</p></section></article>\n<article id=\"entry-dgp-40842\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Τρῶες, Τρώων</h1><div class=\"entry-meta\"><span>DGP · ordem 1384 na letra τ · nº geral 40842</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dat. pl. Τρωσί, ép. Τρώεσσι (οἱ) os troianos.</p></section></article>\n<article id=\"entry-dgp-40843\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Τρωΐα</h1><div class=\"entry-meta\"><span>DGP · ordem 1385 na letra τ · nº geral 40843</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Τροία.</p></section></article>\n<article id=\"entry-dgp-40844\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Τρωϊάς,</h1><div class=\"entry-meta\"><span>DGP · ordem 1386 na letra τ · nº geral 40844</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">contr. Τρῳάς, άδος (fem.) 1 de Troia; troiano, troiana ♦ ἡ Τρωϊάς 2 Tróade 3 pl. as troianas. 〈Τρῶες〉</p></section></article>\n<article id=\"entry-dgp-40845\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Τρωϊκός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1387 na letra τ · nº geral 40845</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de Troia; troiano ♦ τὰ Τρωϊκά 2 os acontecimentos de Troia, i.e., a guerra de Troia. 〈Τρῶες〉</p></section></article>\n<article id=\"entry-dgp-40846\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Τρώϊος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1388 na letra τ · nº geral 40846</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e, contr., Τρῷος, ῴα, ῷον 1 de Troia; troiano ♦ οἱ Τρώιοι 2 os troianos. 〈Τρῶες〉</p></section></article>\n<article id=\"entry-dgp-40847\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Τρωΐς, ΐδος</h1><div class=\"entry-meta\"><span>DGP · ordem 1389 na letra τ · nº geral 40847</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fem.) = Τρωϊάς.</p></section></article>\n<article id=\"entry-dgp-40848\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τρώκτης, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 1390 na letra τ · nº geral 40848</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) 1 que come; que trinca frutos crus (nozes, amêndoas) 2 ávido; voraz; rapace (pessoa).</p></section></article>\n<article id=\"entry-dgp-40849\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τρωκτός, ή,</h1><div class=\"entry-meta\"><span>DGP · ordem 1391 na letra τ · nº geral 40849</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">όν 1 que se pode trincar ou comer ♦ τὰ τρωκτά 2 guloseimas de sobremesa; sobremesa: τρ. σησάμου τε καὶ μέλιτος her. doces de sésamo e mel. 〈τρώγω〉</p></section></article>\n<article id=\"entry-dgp-40850\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τρῶμα, τρωματίζω, τρωματίης</h1><div class=\"entry-meta\"><span>DGP · ordem 1392 na letra τ · nº geral 40850</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = τραῦμα, τραυματίζω, τραυματίας.</p></section></article>\n<article id=\"entry-dgp-40851\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Τρῳός</h1><div class=\"entry-meta\"><span>DGP · ordem 1393 na letra τ · nº geral 40851</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Τρώϊος.</p></section></article>\n<article id=\"entry-dgp-40852\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τρωπάσκετο</h1><div class=\"entry-meta\"><span>DGP · ordem 1394 na letra τ · nº geral 40852</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3a sing. impf. iter. méd. de τρωπάω.</p></section></article>\n<article id=\"entry-dgp-40853\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τρωπάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1395 na letra τ · nº geral 40853</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">poét. 1 virar; flexionar ♦ méd. 2 virar-se para retornar; desviar-se. 〈τρέπω〉</p></section></article>\n<article id=\"entry-dgp-40854\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τρῶσις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1396 na letra τ · nº geral 40854</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ação de machucar, de ferir; ferimento. 〈τιτρώσκω〉</p></section></article>\n<article id=\"entry-dgp-40855\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τρώσω</h1><div class=\"entry-meta\"><span>DGP · ordem 1397 na letra τ · nº geral 40855</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fut. de τιτρώσκω.</p></section></article>\n<article id=\"entry-dgp-40856\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τρωτός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1398 na letra τ · nº geral 40856</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">vulnerável. 〈τιτρώσκω〉</p></section></article>\n<article id=\"entry-dgp-40857\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τρωχάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1399 na letra τ · nº geral 40857</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">τρέχω.</p></section></article>\n<article id=\"entry-dgp-40858\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τρώχων</h1><div class=\"entry-meta\"><span>DGP · ordem 1400 na letra τ · nº geral 40858</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">impf. poét. de τρωχάω.</p></section></article>\n<article id=\"entry-dgp-40859\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τρώω</h1><div class=\"entry-meta\"><span>DGP · ordem 1401 na letra τ · nº geral 40859</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só 3a sing. pres.) = τιτρώσκω.</p></section></article>\n<article id=\"entry-dgp-40860\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τύ</h1><div class=\"entry-meta\"><span>DGP · ordem 1402 na letra τ · nº geral 40860</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dór. = σύ.</p></section></article>\n<article id=\"entry-dgp-40861\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τυγχάνω</h1><div class=\"entry-meta\"><span>DGP · ordem 1403 na letra τ · nº geral 40861</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. τεύξομαι, aor.2 ἔτυχον, perf. τετύχηκα ) 1 atingir algo ou alguém, ac. ou gen. 2 encontrar por acaso; deparar algo, gen. 3 ser bem sucedido; ter sorte de, part. 4 obter por acaso; alcançar; conseguir, gen. ou ac. ou inf., da parte de alguém, gen. ou παρά, πρός, ἐκ ou ὑπό e gen. 5 fazer valer algo, gen. 6 falar atingindo o ponto, na medida certa; encontrar a expressão justa 7 intr. encontrar-se; estar presente por acaso ou justamente 8 estar ocupado com; estar às voltas com algo, ἐν ou ἐπί e dat. 9 acontecer por acaso; suceder; caber por sorte a alguém, dat. 10 modalizador (idéia de coincidência, de casualidade) calhar de, part., às vezes com part. de εἶναι subent.</p></section></article>\n<article id=\"entry-dgp-40862\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τυχόν</h1><div class=\"entry-meta\"><span>DGP · ordem 1404 na letra τ · nº geral 40862</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">part. aor. n. 11 part. abs. sendo por mero acaso 12 adv. talvez; pode ser que 1 τ. αἶγα hom. atingir uma cabra, τ. τοῦ σκοποῦ pínd. atingir o alvo, ἤμβροτες οὐδ’ ἔτυχες hom. erraste o alvo e não [o] atingiste, Ἱππόμαχον βάλε δουρὶ κατὰ ζωστῆρα τυχήσας hom. acertou Hipômaco, tendo[-o] atingido com a lança na região do cinturão, ἵησι τῇ βώλῳ καὶ παρελαύνοντος Φεραύλα τυγχάνει xen. atira o terrão e atinge Feraulas, que passava a galope 2 τ. ἀμάθοιο βαθείης hom. deparar areal profundo, ὁ τυχών át. a primeira pessoa que aparece 3 οὐκ ἐτύχησεν ἑλίξας hom. não obteve sucesso em fazer a volta, i.e., não virou bem, τὸ τυχεῖν pínd. o sucesso, a vitória 4 τ. νόστου hom. conseguir o retorno, τ. σωτηρίας ésql. obter a salvação, a libertação, τ. τραυμάτων ésql. receber ferimentos, αἰτεῖς ἃ τεύξει sóf. pedes o que obterás, i.e., terás o que pedes, τ. τὸ θανεῖν sóf. encontrar a morte, ὧν σου τυχεῖν ἐφίεμαι sóf. o que quero obter de ti, τυγχάνων sóf. que consegue, que tem sucesso, τυχών tuc. que conseguiu, que foi bem sucedido 5 τυχεῖν τῆς γνώμης tuc. fazer prevalecer sua opinião, τῆς ἑκάστου βουλήσεώς τε καὶ δόξης τυχεῖν tuc. satisfazer o desejo e a opinião de cada um 6 εἰ μή τι καιροῦ τυγχάνω sóf. se não estou certo, se não falo nenhuma impropriedade 7 μὴ σύ γε κεῖθι τύχοις hom. possas não estar lá [no momento da sucção], ὃν πέρι πέτρη ἡλίβατος τετύχηκε hom. circundando-o [o porto] encontrava-se uma rocha íngreme, εἴ πέρ τε τυχῄσι μάλα σχεδόν hom. mesmo que [a corça] esteja muito perto, ἐνεπαύοντο ὅπου ἐτύγχανεν ἕκαστος xen. eles pararam onde cada um se encontrava, νῦν δ᾽ ἀγροῖσι τυγχάνει sóf. neste momento ele se encontra no campo 8 τυγχάνει δ᾽ ἐμπύροις eur. [Febo] estava ocupado com sacrifícios 9 καί μοι μάλα τύγχανε πολλά hom. coube-me grande quantia de despojos, οἷ᾽ αὐτοῖς τύχοι sóf. possa acontecer-lhes algo parecido! εὔχου τὰ λοιπὰ τυγχάνειν καλῶς ésql. reza para que o resto resulte bem, οὐκ ἐλήρουν ὅ τι τύχοιμ᾽ ar. eu não dizia o que me vinha à cabeça, ὁ τυχών o primeiro que aparece, aquele que se encontra ao alcance, homem comum, ὁ τυχὼν καὶ οὐδὲ προσήκων ἔρχεται ἐπ᾽ αὐτό plat. um qualquer que, mesmo sem qualificação, entrega-se a isso [participação nos discursos], παρὰ τοῦ τυχόντος χρήματα λαμβάνειν xen. receber dinheiro do primeiro que aparecer, οἷς ἔτυχε προσκρούων plut. colidindo com aqueles que encontrasse, εἷς τῶν τυχόντων xen. um dos primeiros que aparecem, εἷς ἦν τῶν τυχόντων isócr. era um dentre os homens comuns, τὸ τυγχάνον e τὰ τυγχάνοντα os acontecimentos, τὰ τυχόντα as coisas comuns, ordinárias, de pouca importância, οὐχ ὁ τυχὼν λόγος Plat.discurso não comum, ἔτυχε át. ou ὅπως ou ὡς ἔτυχε xen. como (isso) estava, por acaso, não importa como, ποιοῦσι τοῦτο ὅ τι ἂν τύχωσι plat. fazem o que encontram (qualquer coisa, o que podem), i.e., a primeira coisa que aparece, o possível, ὁπόθεν τύχοιεν tuc. de onde quer que estivessem, ὡς ἕκαστοι ἔτυχον tuc. como sucedia para cada um, i.e., de um modo variável, σκήπτομαί γ᾽ ὅταν τύχω ar. finjo [ser mercador] sempre que preciso 10 τυγχάνω ἔχων át. calha de eu ter, τὰ νοέων τυγχάνω her. justamente o que estou pensando, ἔτυχον γὰρ ἐς Κύπρον στρατευόμενοι ναυσὶ διακοσίαις αὐτῶν τε καὶ τῶν ξυμμάχων tuc. estava justamente a caminho de Chipre uma expedição de duzentos navios seus e dos aliados, ἔφη τυχεῖν ἐὼν ἅμα Δημαρήτῳ her. disse, justamente, que estava com Demáratos, ἔτυχε γὰρ ὁ Φεραύλας παραγγέλλων τι τακτὸς παρὰ τοῦ Κύρου xen. pois calhava que Feraulas, a mandado de Ciro, trazia uma mensagem, τυγχάνει ἡμῶν ἕκαστος οὐκ αὐτάρκης, ἀλλὰ πολλῶν [ὢν] ἐνδεής plat. calha que cada um de nós não é autossuficiente, mas carente de muitas coisas, μέγιστος τυγχάνει δορυξένων sóf. pois acontece que ele é o maior dentre seus companheiros, τὸ ἀπαράσκευοι τότε τυχεῖν tuc. o fato de encontrarem-se despreparados no momento 11 ἡ δὲ ὄρνις [ἡ πρὸ τοῦ Ἕρμωνος] πιμελεστέρα, οὕτως, οἶμαι, τυχόν luc. mas a galinha que estava diante de Hermão era mais gorda, e isso, penso eu, por mero acaso 12 πρὸς ὑμᾶς δὲ τυχὸν παραμενῶ n.t. pode ser que eu permaneça junto de vós, καὶ Ἀλέξανδρος ἀφῆκε, τυχὸν μὲν αἰδοῖ τῆς πόλεως, τυχὸν δὲ σπουδῇ τοῦ ἐς τὴν Ἀσίαν στόλου, οὐκ ἐθέλων οὐδὲν ὕποπτον ἐν τοῖς Ἕλλησιν ὑπολείπεσθαι arr. e Alexandre poupou[-os], talvez por consideração à cidade, ou talvez, em vista da iminência do ataque à Ásia, por não querer deixar entre os helenos nenhum motivo de descontentamento.</p></section></article>\n<article id=\"entry-dgp-40863\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Τυδείδης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1405 na letra τ · nº geral 40863</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">filho de Tideu, Diomedes.</p></section></article>\n<article id=\"entry-dgp-40864\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Τυδεύς, έως (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1406 na letra τ · nº geral 40864</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Tideu, pai de Diomedes.</p></section></article>\n<article id=\"entry-dgp-40865\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τῦκον</h1><div class=\"entry-meta\"><span>DGP · ordem 1407 na letra τ · nº geral 40865</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">beóc. = σῦκον.</p></section></article>\n<article id=\"entry-dgp-40866\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τύκος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1408 na letra τ · nº geral 40866</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 picareta 2 acha d᾽ armas. 〈τεύχω〉</p></section></article>\n<article id=\"entry-dgp-40867\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τυκτά</h1><div class=\"entry-meta\"><span>DGP · ordem 1409 na letra τ · nº geral 40867</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pal. persa, refinado; suntuoso (banquete).</p></section></article>\n<article id=\"entry-dgp-40868\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τυκτός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1410 na letra τ · nº geral 40868</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 produzido pelo homem: τυκτὸν κακόν hom. mal que os homens fazem a si mesmos 2 feito com arte; trabalhado com arte 3 sólido; firme. 〈τεύχω〉</p></section></article>\n<article id=\"entry-dgp-40869\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τυλεῖον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1411 na letra τ · nº geral 40869</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dim. de τύλη.</p></section></article>\n<article id=\"entry-dgp-40870\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τύλη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1412 na letra τ · nº geral 40870</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 bossa ou protuberância 2 calo; calosidade no pescoço ou nas costas de carregador 3 espécie de almofada para amortecer o peso de fardo 4 almofada; colchão.</p></section></article>\n<article id=\"entry-dgp-40871\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τύλος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1413 na letra τ · nº geral 40871</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 calo; calosidade 2 Náut. cavilha 3 nó; prego de bastão, de maça 4 membro viril.</p></section></article>\n<article id=\"entry-dgp-40872\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τυλόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1414 na letra τ · nº geral 40872</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 tornar caloso 2 guarnecer de nós, de pregos (maça) 3 calejar; tornar insensível ♦ pas. 4 tornar-se duro, insensível, calejado.</p></section></article>\n<article id=\"entry-dgp-40873\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τυλώδης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 1415 na letra τ · nº geral 40873</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">caloso; endurecido. 〈τύλος, -ωδης〉</p></section></article>\n<article id=\"entry-dgp-40874\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τυλωτός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1416 na letra τ · nº geral 40874</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">guarnecido de pregos (maça). 〈τυλόω〉</p></section></article>\n<article id=\"entry-dgp-40875\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τυμβαύλης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1417 na letra τ · nº geral 40875</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">flautista de funerais. 〈τύμβος, αὐλέω〉</p></section></article>\n<article id=\"entry-dgp-40876\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τύμβευμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1418 na letra τ · nº geral 40876</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 túmulo; sepultura; tumba 2 corpo sepultado ou a sepultar; cadáver. 〈τυμβεύω〉</p></section></article>\n<article id=\"entry-dgp-40877\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τυμβεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 1419 na letra τ · nº geral 40877</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 amortalhar; sepultar 2 derramar (libação), ac., sobre um túmulo: πατρὶ τυμβεῦσαι χοάς Sóf. derramar libações no túmulo em honra do pai 3 intr. jazer no túmulo.</p></section></article>\n<article id=\"entry-dgp-40878\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τυμβήρης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 1420 na letra τ · nº geral 40878</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 amortalhado; enterrado; sepulto 2 sepulcral; funerário. 〈τύμβος, ἀραρίσκω〉</p></section></article>\n<article id=\"entry-dgp-40879\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τύμβος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1421 na letra τ · nº geral 40879</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 cômoro para sepultura: τύμβον χεῦαι hom., τύμβον χῶσαι sóf. amontoar o cômoro, i.e., a terra do túmulo 2 túmulo 3 pedra sepulcral 4 com. pé-na-cova (pessoa).</p></section></article>\n<article id=\"entry-dgp-40880\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τυμβοχοέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1422 na letra τ · nº geral 40880</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 erigir um cômoro funerário 2 enterrar em túmulo. 〈τυμβοχόος〉</p></section></article>\n<article id=\"entry-dgp-40881\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τυμβοχόος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1423 na letra τ · nº geral 40881</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que verte libações em um túmulo ♦ ὁ τυμβοχόος 2 coveiro. 〈τύμβος, χέω〉</p></section></article>\n<article id=\"entry-dgp-40882\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τυμβόχωστος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1424 na letra τ · nº geral 40882</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">amontoado em forma de túmulo; sepulcral. 〈τύμβος, χώννυμι〉</p></section></article>\n<article id=\"entry-dgp-40883\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τυμβωρυχέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1425 na letra τ · nº geral 40883</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cavar sepulturas para roubar ou devorar os cadáveres. 〈τυμβωρύχος〉</p></section></article>\n<article id=\"entry-dgp-40884\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τυμβωρύχος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1426 na letra τ · nº geral 40884</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que escava um túmulo 2 violador de sepulcro; ladrão de sepulturas. 〈τύμβος, ὀρύσσω〉</p></section></article>\n<article id=\"entry-dgp-40885\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τύμμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1427 na letra τ · nº geral 40885</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">golpe; ferimento. 〈τύπτω〉</p></section></article>\n<article id=\"entry-dgp-40886\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τυμπανίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1428 na letra τ · nº geral 40886</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 tocar tímpano 2 bater repetidamente (numa porta) 3 (orador) gesticular com vigor ♦ pas. 4 ser acompanhado pelo som do tímpano 5 ser fixado no poste de tortura; ser torturado. 〈τύμπανον〉</p></section></article>\n<article id=\"entry-dgp-40887\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τυμπανισμός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1429 na letra τ · nº geral 40887</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ação de tocar tímpano no culto de Cibele 2 ministério dos sacerdotes de Cibele. 〈τυμπανίζω〉</p></section></article>\n<article id=\"entry-dgp-40888\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τυμπανιστής, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1430 na letra τ · nº geral 40888</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 tocador de tímpano 2 tímpano.</p></section></article>\n<article id=\"entry-dgp-40889\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τυμπανίστρια, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1431 na letra τ · nº geral 40889</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fem. de τυμπανιστής.</p></section></article>\n<article id=\"entry-dgp-40890\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τυμπανοειδής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 1432 na letra τ · nº geral 40890</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que se assemelha a um tímpano. 〈τύμπανον, εἶδος〉</p></section></article>\n<article id=\"entry-dgp-40891\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τύμπανον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1433 na letra τ · nº geral 40891</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 tímpano; tamborim 2 aparelho de tortura ou de execução para aplicar a bastonada 3 cilindro; disco de pistão, em mecanismos 4 Arquit. tímpano.</p></section></article>\n<article id=\"entry-dgp-40892\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Τυνδάρειος, α</h1><div class=\"entry-meta\"><span>DGP · ordem 1434 na letra τ · nº geral 40892</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e ος, ον de Tindareu.</p></section></article>\n<article id=\"entry-dgp-40893\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Τυνδάρεος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1435 na letra τ · nº geral 40893</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Tindareu, pai de Castor e Pólux, de Helena e de Clitemnestra.</p></section></article>\n<article id=\"entry-dgp-40894\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Τυνδάρεως</h1><div class=\"entry-meta\"><span>DGP · ordem 1436 na letra τ · nº geral 40894</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. e át. = Τυνδάρεος.</p></section></article>\n<article id=\"entry-dgp-40895\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Τυνδαρίδης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1437 na letra τ · nº geral 40895</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">filho ou descendente de Tindareu; Tindárida. 〈Τυνδάρεος〉</p></section></article>\n<article id=\"entry-dgp-40896\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τύνη</h1><div class=\"entry-meta\"><span>DGP · ordem 1438 na letra τ · nº geral 40896</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ép. = σύ.</p></section></article>\n<article id=\"entry-dgp-40897\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τυννοῦτος</h1><div class=\"entry-meta\"><span>DGP · ordem 1439 na letra τ · nº geral 40897</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) e τυννοῦτον (n.) muito pequeno; pequetito.</p></section></article>\n<article id=\"entry-dgp-40898\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τυπή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1440 na letra τ · nº geral 40898</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ger. pl. golpe. 〈τύπτω〉</p></section></article>\n<article id=\"entry-dgp-40899\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τυπικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1441 na letra τ · nº geral 40899</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 maleável; flexível 2 que representa alegoricamente; simbólico 3 Medic. concordante com o tipo. 〈τύπος〉</p></section></article>\n<article id=\"entry-dgp-40900\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τυπικῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 1442 na letra τ · nº geral 40900</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 em conformidade com o tipo 2 bíbl. simbolicamente; figurativamente.</p></section></article>\n";
